INSERT INTO easa_subjects (module_id, code, title, sort_order) VALUES
  (2, 'M02.6', 'Exam Question Bank', 6)
    INSERT INTO questions (subject_id, text, options, licence_types) VALUES
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'An atom with 3 free electrons in its outer shell is said to be', '[{"id": "a", "text": "pentavalent.", "correct": false}, {"id": "b", "text": "covalent.", "correct": false}, {"id": "c", "text": "trivalent.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'What is the mass number of an element?', '[{"id": "a", "text": "Number of electrons and protons.", "correct": false}, {"id": "b", "text": "Number of neutrons and protons.", "correct": true}, {"id": "c", "text": "Number of electrons and neutrons.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'What do you get when you add 2H₂ and O?', '[{"id": "a", "text": "H₂O", "correct": false}, {"id": "b", "text": "2H₂O", "correct": true}, {"id": "c", "text": "2H₂O₂", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'The splitting of a chemical compound is called', '[{"id": "a", "text": "bombardment.", "correct": false}, {"id": "b", "text": "synthesis.", "correct": false}, {"id": "c", "text": "analysis.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'What is the atomic number of an element?', '[{"id": "a", "text": "The number of neutrons in the atom.", "correct": false}, {"id": "b", "text": "The number of electrons in the atom.", "correct": false}, {"id": "c", "text": "The number of protons in the atom.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'An atom with 5 free electrons is said to be', '[{"id": "a", "text": "pentavalent.", "correct": true}, {"id": "b", "text": "covalent.", "correct": false}, {"id": "c", "text": "Trivalent", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'An atom consists of', '[{"id": "a", "text": "protons, neutrons and electrons.", "correct": true}, {"id": "b", "text": "protons and electrons.", "correct": false}, {"id": "c", "text": "protons and neutrons.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'The maximum number of electrons in the inner shell of an atom is', '[{"id": "a", "text": "8.", "correct": false}, {"id": "b", "text": "2.", "correct": true}, {"id": "c", "text": "4.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'The mass of a proton equals the mass of a', '[{"id": "a", "text": "neutron.", "correct": true}, {"id": "b", "text": "beta particle.", "correct": false}, {"id": "c", "text": "electron.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'Catalysts', '[{"id": "a", "text": "speed up reactions.", "correct": true}, {"id": "b", "text": "speed up and slow down reactions.", "correct": false}, {"id": "c", "text": "slow down reactions.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'If the outer shell of an atom is full then the element is', '[{"id": "a", "text": "unstable / reactive.", "correct": false}, {"id": "b", "text": "a good conductor.", "correct": false}, {"id": "c", "text": "practically inert.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'Molecules of the same compound are held together by', '[{"id": "a", "text": "cohesive forces.", "correct": true}, {"id": "b", "text": "adhesive forces.", "correct": false}, {"id": "c", "text": "gravitational forces.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'Oxygen has a valency of', '[{"id": "a", "text": "2.", "correct": true}, {"id": "b", "text": "6.", "correct": false}, {"id": "c", "text": "8.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'The further from the nucleus the shells are in an atom', '[{"id": "a", "text": "the shells retain the same spacing from each other.", "correct": false}, {"id": "b", "text": "the closer the shells get to each other.", "correct": true}, {"id": "c", "text": "the further the shells get from each other", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'What determines an element''s identity?', '[{"id": "a", "text": "The number of neutrons.", "correct": false}, {"id": "b", "text": "The number of electrons.", "correct": false}, {"id": "c", "text": "The number of protons.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'An isotope of an element will have more/less _________ than usual.', '[{"id": "a", "text": "electrons", "correct": false}, {"id": "b", "text": "neutrons", "correct": true}, {"id": "c", "text": "protons", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'The smallest part of an element is', '[{"id": "a", "text": "a compound.", "correct": false}, {"id": "b", "text": "an atom.", "correct": true}, {"id": "c", "text": "a molecule.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'The nucleus of an atom contains', '[{"id": "a", "text": "protons and electrons.", "correct": false}, {"id": "b", "text": "protons and neutrons.", "correct": true}, {"id": "c", "text": "electrons and neutrons.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'What is atomic mass?', '[{"id": "a", "text": "Number of neutrons.", "correct": false}, {"id": "b", "text": "Number of protons plus the number of neutrons.", "correct": true}, {"id": "c", "text": "Number of protons.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'An ice melted into a liquid will take up', '[{"id": "a", "text": "the same amount of space.", "correct": false}, {"id": "b", "text": "less space.", "correct": true}, {"id": "c", "text": "more space.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'What form of heat is used to turn a solid into a liquid?', '[{"id": "a", "text": "specific heat", "correct": false}, {"id": "b", "text": "coefficient of heat", "correct": false}, {"id": "c", "text": "heat of fusion", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'Change from solid to gas state without going through liquid state is called', '[{"id": "a", "text": "transformation.", "correct": false}, {"id": "b", "text": "sublimation.", "correct": true}, {"id": "c", "text": "state leap.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'What is the smallest particle of matter that can exist in nature?', '[{"id": "a", "text": "A molecule.", "correct": false}, {"id": "b", "text": "An isotope.", "correct": false}, {"id": "c", "text": "An atom.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'A positive ion', '[{"id": "a", "text": "has extra electrons.", "correct": false}, {"id": "b", "text": "has missing electrons.", "correct": true}, {"id": "c", "text": "is a radioactive isotope.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'The isotope of a carbon atom C-14 to C-12 will have', '[{"id": "a", "text": "same numbers of neutrons.", "correct": false}, {"id": "b", "text": "same numbers of protons.", "correct": true}, {"id": "c", "text": "same number of electrons.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'If an atom has 2 protons, how many electrons will it have?', '[{"id": "a", "text": "1.", "correct": false}, {"id": "b", "text": "8.", "correct": false}, {"id": "c", "text": "2.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'A molecule with like atoms is said to be a', '[{"id": "a", "text": "neutroid.", "correct": false}, {"id": "b", "text": "compound.", "correct": false}, {"id": "c", "text": "element.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'Two elements in the same substance is said to be a', '[{"id": "a", "text": "mixture.", "correct": false}, {"id": "b", "text": "element.", "correct": false}, {"id": "c", "text": "compound.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'The number of protons in an atom is equal to the number of', '[{"id": "a", "text": "electrons.", "correct": true}, {"id": "b", "text": "neutrons.", "correct": false}, {"id": "c", "text": "mass number.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'The charge of an electron is', '[{"id": "a", "text": "neutral.", "correct": false}, {"id": "b", "text": "negative.", "correct": true}, {"id": "c", "text": "positive.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'A valence electron is an electron', '[{"id": "a", "text": "in the innermost shell.", "correct": false}, {"id": "b", "text": "in the outermost shell.", "correct": true}, {"id": "c", "text": "which is not within an atom.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'Molecules of unlike atoms are combined by their', '[{"id": "a", "text": "adhesive force.", "correct": true}, {"id": "b", "text": "magnetic force.", "correct": false}, {"id": "c", "text": "cohesive force.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'What is the difference between hydrogen, deuterium and tritium?', '[{"id": "a", "text": "The number of electrons.", "correct": false}, {"id": "b", "text": "The number of protons.", "correct": false}, {"id": "c", "text": "The number of neutrons.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'The smallest material in the universe is', '[{"id": "a", "text": "an ion.", "correct": false}, {"id": "b", "text": "helium.", "correct": false}, {"id": "c", "text": "hydrogen.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'What is the atomic number of the element shown here? ⁴₃H (it is not hydrogen, just a fictional element)', '[{"id": "a", "text": "4.", "correct": false}, {"id": "b", "text": "3.", "correct": true}, {"id": "c", "text": "7.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'What is the mass number of the element shown here? ⁵₄Cl', '[{"id": "a", "text": "4", "correct": false}, {"id": "b", "text": "5", "correct": true}, {"id": "c", "text": "9", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'There are solids, liquids and gases present in the universe and every unit of theirs occupy some space. This is called', '[{"id": "a", "text": "matter.", "correct": true}, {"id": "b", "text": "compound.", "correct": false}, {"id": "c", "text": "mass.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'An atom deficient of a valency electron is deficient', '[{"id": "a", "text": "of an electron in the outer shell.", "correct": true}, {"id": "b", "text": "of a neutron in the outer shell.", "correct": false}, {"id": "c", "text": "of an electron in the inner shell.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'The maximum number of electrons in the second shell is', '[{"id": "a", "text": "4.", "correct": false}, {"id": "b", "text": "8.", "correct": true}, {"id": "c", "text": "2.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'What does an oxygen atom consist of?', '[{"id": "a", "text": "Protons, neutrons and electrons.", "correct": true}, {"id": "b", "text": "Protons and electrons.", "correct": false}, {"id": "c", "text": "Protons and neutrons.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'Surface molecular attraction between two different molecules is', '[{"id": "a", "text": "adhesive.", "correct": true}, {"id": "b", "text": "gravitational.", "correct": false}, {"id": "c", "text": "cohesive.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'The atomic mass number is the number of', '[{"id": "a", "text": "protons plus electrons.", "correct": false}, {"id": "b", "text": "neutrons plus electrons.", "correct": false}, {"id": "c", "text": "protons plus neutrons.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'A catalyst in a chemical reaction does what?', '[{"id": "a", "text": "Can either speed it up or slow it down.", "correct": false}, {"id": "b", "text": "Speeds it up.", "correct": true}, {"id": "c", "text": "Slows it down.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'What is the number of electrons in the inner-most shell of an atom?', '[{"id": "a", "text": "4.", "correct": false}, {"id": "b", "text": "8.", "correct": false}, {"id": "c", "text": "2.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'What form of heat is used to turn a solid into a gas?', '[{"id": "a", "text": "Sensible heat.", "correct": false}, {"id": "b", "text": "Specific heat.", "correct": false}, {"id": "c", "text": "Latent heat.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'The heat required to change a liquid to a gas at constant temperature is the heat of', '[{"id": "a", "text": "fusion.", "correct": false}, {"id": "b", "text": "condensation.", "correct": false}, {"id": "c", "text": "vaporisation.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'An atom with a full outer shell is', '[{"id": "a", "text": "practically inert.", "correct": true}, {"id": "b", "text": "a good insulator.", "correct": false}, {"id": "c", "text": "a good conductor.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'An element with a full valence shell is', '[{"id": "a", "text": "very reactive.", "correct": false}, {"id": "b", "text": "good conductor.", "correct": false}, {"id": "c", "text": "inert.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'A substance of two or more different atoms is', '[{"id": "a", "text": "a neutrino.", "correct": false}, {"id": "b", "text": "an isotope.", "correct": false}, {"id": "c", "text": "a chemical compound.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'An atom with 5 electrons in its outer shell is', '[{"id": "a", "text": "Trivalent.", "correct": false}, {"id": "b", "text": "pentavalent.", "correct": true}, {"id": "c", "text": "covalent.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'Protons have', '[{"id": "a", "text": "no charge.", "correct": false}, {"id": "b", "text": "positive charge.", "correct": true}, {"id": "c", "text": "negative charge.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'Producing a compound from commonly available materials is', '[{"id": "a", "text": "synthesis.", "correct": true}, {"id": "b", "text": "analysis.", "correct": false}, {"id": "c", "text": "bombardment.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'A different number of nucleons in the nucleus of atoms would represent', '[{"id": "a", "text": "semiconductor.", "correct": false}, {"id": "b", "text": "isotopes.", "correct": true}, {"id": "c", "text": "isotones.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'Molecules of matter are in constant motion. The amount of vibration or motion is dependent on', '[{"id": "a", "text": "temperature.", "correct": true}, {"id": "b", "text": "volume.", "correct": false}, {"id": "c", "text": "pressure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'When a chemical change takes place, the smallest particle indivisible in an element is called', '[{"id": "a", "text": "an atom.", "correct": true}, {"id": "b", "text": "an electron.", "correct": false}, {"id": "c", "text": "a neutron.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'A nucleus of an atom consists of', '[{"id": "a", "text": "positively charged particles.", "correct": true}, {"id": "b", "text": "a nucleus and normally has no overall charge at all and so is neutral.", "correct": false}, {"id": "c", "text": "negatively charged particles.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'A compound is a', '[{"id": "a", "text": "mixture of more than one element which are chemically bonded together.", "correct": true}, {"id": "b", "text": "solution (either liquid or solid) of elements or mixtures of elements to form a new material.", "correct": false}, {"id": "c", "text": "mixture of more than one element which are mixed together.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'A compound such as water can exist in how many states?', '[{"id": "a", "text": "2.", "correct": false}, {"id": "b", "text": "3.", "correct": true}, {"id": "c", "text": "1.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'Select the correct statement from the following.', '[{"id": "a", "text": "Temperature is the only factor which can affect the state in which matter exists.", "correct": false}, {"id": "b", "text": "Matter can only exist in one of three states.", "correct": true}, {"id": "c", "text": "As temperature rises a solid will always become a liquid and then a gas.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'Isotopes of an element have', '[{"id": "a", "text": "a different atomic number.", "correct": false}, {"id": "b", "text": "the same number of neutrons but a different number of protons.", "correct": false}, {"id": "c", "text": "the same number of protons but a different number of neutrons.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'Neutrons have', '[{"id": "a", "text": "no charge.", "correct": true}, {"id": "b", "text": "a positive charge.", "correct": false}, {"id": "c", "text": "a negative charge.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'Atomic MASS number is the number of', '[{"id": "a", "text": "protons.", "correct": false}, {"id": "b", "text": "protons and neutrons.", "correct": true}, {"id": "c", "text": "electrons.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'How many electrons does an `S` orbital hold?', '[{"id": "a", "text": "6.", "correct": false}, {"id": "b", "text": "8.", "correct": false}, {"id": "c", "text": "2.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'The number of electrons in a stable atom equals', '[{"id": "a", "text": "the number of neutrons in the nucleus.", "correct": false}, {"id": "b", "text": "the number of protons and neutrons in the nucleus.", "correct": false}, {"id": "c", "text": "the number of protons in the nucleus.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'An isotope of an element has', '[{"id": "a", "text": "the same atomic number but a different mass number.", "correct": true}, {"id": "b", "text": "the same mass number but a different atomic number.", "correct": false}, {"id": "c", "text": "a different mass and atomic number.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'The mass number of an element is based on', '[{"id": "a", "text": "the total number of protons and neutrons in its nucleus.", "correct": true}, {"id": "b", "text": "the number of protons in its nucleus.", "correct": false}, {"id": "c", "text": "the number of neutrons in its nucleus.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'The atomic weight of all atoms is related to', '[{"id": "a", "text": "Hydrogen.", "correct": false}, {"id": "b", "text": "Carbon.", "correct": true}, {"id": "c", "text": "Helium.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'The chemical bonding of two or more elements is called', '[{"id": "a", "text": "chemical analysis.", "correct": false}, {"id": "b", "text": "chemical synthesis.", "correct": true}, {"id": "c", "text": "chemical fusion.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'Two or more elements that are chemically bonded together and have an even mass distribution form a', '[{"id": "a", "text": "mixture.", "correct": false}, {"id": "b", "text": "substance.", "correct": false}, {"id": "c", "text": "chemical compound.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'An atom that gains one or more additional electrons is called', '[{"id": "a", "text": "a negative ion.", "correct": true}, {"id": "b", "text": "a positive ion.", "correct": false}, {"id": "c", "text": "an isotope.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'Ionic bonding involves', '[{"id": "a", "text": "electron sharing.", "correct": false}, {"id": "b", "text": "attraction to a free electron cloud.", "correct": false}, {"id": "c", "text": "electron transfer.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'Non-metals form', '[{"id": "a", "text": "covalent bonds.", "correct": true}, {"id": "b", "text": "ionic bond.", "correct": false}, {"id": "c", "text": "metallic bonds.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'Brownian Movement describes', '[{"id": "a", "text": "the attraction of neutrons.", "correct": false}, {"id": "b", "text": "the attraction of electrons.", "correct": false}, {"id": "c", "text": "the motion of molecules.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'Elements on the extreme right of the periodic table are', '[{"id": "a", "text": "metals.", "correct": false}, {"id": "b", "text": "non-metals.", "correct": true}, {"id": "c", "text": "transition metals.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'Oxygen, atomic number 8 is', '[{"id": "a", "text": "trivalent.", "correct": false}, {"id": "b", "text": "univalent.", "correct": false}, {"id": "c", "text": "bivalent.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'The atomic number of the atom of an element is based on', '[{"id": "a", "text": "the number of neutrons in to nucleus.", "correct": false}, {"id": "b", "text": "the number of protons in its nucleus.", "correct": true}, {"id": "c", "text": "the total number of protons and neutrons in its nucleus.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'Water is', '[{"id": "a", "text": "an element.", "correct": false}, {"id": "b", "text": "a mixture.", "correct": false}, {"id": "c", "text": "a compound.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'The Mass of a Proton is approximately', '[{"id": "a", "text": "equal to the mass of an electron.", "correct": false}, {"id": "b", "text": "equal to the relative mass of a molecule.", "correct": false}, {"id": "c", "text": "2000 times greater than the mass of an electron.", "correct": true}]'::jsonb, '{B1,B2}'),
