    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'A majority of an atom''s mass is in the', '[{"id": "a", "text": "compound.", "correct": false}, {"id": "b", "text": "isotope.", "correct": false}, {"id": "c", "text": "nucleus.", "correct": true}]'::jsonb, '{B1,B2}'),
