    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'For the CGS system, the force is', '[{"id": "a", "text": "the ''N'', which produces an acceleration of 1 cm/s² for a mass of one gram.", "correct": false}, {"id": "b", "text": "the ''dyne'', which produces an acceleration of 1 cm/s² for a mass of one gram.", "correct": true}, {"id": "c", "text": "the ''pdl'' (poundal), which produces an acceleration of 1 cm/s² for a mass of one gram.", "correct": false}]'::jsonb, '{B1,B2}'),
