    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), '1 Newton is equal to', '[{"id": "a", "text": "1 kilogram meter per second per second.", "correct": true}, {"id": "b", "text": "1 kilogram of force.", "correct": false}, {"id": "c", "text": "1 joule per second.", "correct": false}]'::jsonb, '{B1,B2}'),
