    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'A slug is a unit of', '[{"id": "a", "text": "speed.", "correct": false}, {"id": "b", "text": "mass.", "correct": true}, {"id": "c", "text": "weight.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'If an object in air is submerged in a liquid or a gas its weight will', '[{"id": "a", "text": "increase.", "correct": false}, {"id": "b", "text": "decrease.", "correct": true}, {"id": "c", "text": "remain the same.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'If a material is loaded excessively and is permanently deformed, it is said to be', '[{"id": "a", "text": "stretched.", "correct": false}, {"id": "b", "text": "stressed.", "correct": false}, {"id": "c", "text": "strained.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'The SI unit of force is the', '[{"id": "a", "text": "Newton (N).", "correct": true}, {"id": "b", "text": "Metre (m).", "correct": false}, {"id": "c", "text": "Pascal (Pa).", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'The formula for calculating stress is', '[{"id": "a", "text": "load divided by cross sectional area.", "correct": true}, {"id": "b", "text": "area divided by load.", "correct": false}, {"id": "c", "text": "load multiplied by cross sectional area.", "correct": false}]'::jsonb, '{B1,B2}'),
