    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'A force perpendicular to a beam produces what type of stress?', '[{"id": "a", "text": "compressive.", "correct": false}, {"id": "b", "text": "shear.", "correct": true}, {"id": "c", "text": "tensile.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'The extension of a spring can be determined using', '[{"id": "a", "text": "Charles'' Law.", "correct": false}, {"id": "b", "text": "Newton''s 2nd Law.", "correct": false}, {"id": "c", "text": "Hooke''s Law.", "correct": true}]'::jsonb, '{B1,B2}'),
