    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'The most common method of expressing pressure is in', '[{"id": "a", "text": "pounds per square inch.", "correct": true}, {"id": "b", "text": "grams per square inch.", "correct": false}, {"id": "c", "text": "inch pounds per square inch.", "correct": false}]'::jsonb, '{B1,B2}'),
