    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'As an object slides down a slope, its', '[{"id": "a", "text": "kinetic energy increases and its potential energy increases.", "correct": false}, {"id": "b", "text": "kinetic energy increases and its potential energy decreases.", "correct": true}, {"id": "c", "text": "kinetic energy decreases and its potential energy increases.", "correct": false}]'::jsonb, '{B1,B2}'),
