    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'When a system undergoes a complete cycle where the net heat supplied is equal to work done plus a change in internal energy - this is known as', '[{"id": "a", "text": "2nd Law of thermodynamics.", "correct": false}, {"id": "b", "text": "First law of thermodynamics.", "correct": true}, {"id": "c", "text": "Ideal Gas law.", "correct": false}]'::jsonb, '{B1,B2}'),
