    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'What is 100 Degrees Centigrade in Fahrenheit?', '[{"id": "a", "text": "30 Degrees.", "correct": false}, {"id": "b", "text": "148 Degrees.", "correct": false}, {"id": "c", "text": "212 Degrees.", "correct": true}]'::jsonb, '{B1,B2}'),
