    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'The specific heat capacity of a gas heated at constant pressure, when compared to the specific heat capacity of a gas heated at constant volume, is', '[{"id": "a", "text": "more.", "correct": true}, {"id": "b", "text": "less.", "correct": false}, {"id": "c", "text": "the same.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'Adiabatic compression is when', '[{"id": "a", "text": "no heat is lost or gained.", "correct": true}, {"id": "b", "text": "kinetic energy is gained.", "correct": false}, {"id": "c", "text": "heat is given off to the surroundings.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'The heat required to change a solid to a liquid is called the heat of', '[{"id": "a", "text": "vapourisation.", "correct": false}, {"id": "b", "text": "condensation.", "correct": false}, {"id": "c", "text": "fusion.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'Latent heat is the', '[{"id": "a", "text": "heat required to raise the temperature of a body by 1 °C.", "correct": false}, {"id": "b", "text": "heat required to raise 1kg of matter by 1K.", "correct": false}, {"id": "c", "text": "heat required to change the state of a body.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'The intensity of radiated heat is', '[{"id": "a", "text": "inversely proportional to the square of the distance from the source of the heat.", "correct": true}, {"id": "b", "text": "not effected by the distance from the source of the heat.", "correct": false}, {"id": "c", "text": "directly proportional to distance from the source of the heat.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'As a block of ice is melted (to 4 °C). Its volume', '[{"id": "a", "text": "remains the same.", "correct": false}, {"id": "b", "text": "decreases.", "correct": true}, {"id": "c", "text": "increases.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'A good refrigerant has', '[{"id": "a", "text": "high condensing pressure, low evaporating temperature.", "correct": false}, {"id": "b", "text": "high condensing pressure, high evaporating temperature.", "correct": false}, {"id": "c", "text": "low condensing pressure, low vaporating temperature.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'In a heat pump', '[{"id": "a", "text": "flow across the condenser is always in one direction.", "correct": false}, {"id": "b", "text": "the condenser loses heat.", "correct": true}, {"id": "c", "text": "the evaporator gains heat during the heating cycle.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'Charles'' Law states that', '[{"id": "a", "text": "volume varies inversely with temperature.", "correct": false}, {"id": "b", "text": "volume varies directly with temperature.", "correct": true}, {"id": "c", "text": "volume equals pressure × temperature.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'Boyle''s law states that', '[{"id": "a", "text": "pressure equals temperature divided by volume.", "correct": false}, {"id": "b", "text": "pressure varies directly with volume.", "correct": false}, {"id": "c", "text": "pressure varies inversely with volume.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'A process where volume does not change is', '[{"id": "a", "text": "isochoric.", "correct": true}, {"id": "b", "text": "isobaric.", "correct": false}, {"id": "c", "text": "isothermic.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'A process where heat is not transferred to or from a gas is', '[{"id": "a", "text": "adiabatic.", "correct": true}, {"id": "b", "text": "isochoric.", "correct": false}, {"id": "c", "text": "isobaric.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'A process where pressure does not change is known as', '[{"id": "a", "text": "isochoric.", "correct": false}, {"id": "b", "text": "isothermic.", "correct": false}, {"id": "c", "text": "isobaric.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'When a liquid is heated, it expands', '[{"id": "a", "text": "more than a solid.", "correct": true}, {"id": "b", "text": "less than a solid.", "correct": false}, {"id": "c", "text": "more than a gas.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'If pressure on a liquid increases, whilst temperature is held constant, the volume will', '[{"id": "a", "text": "decrease.", "correct": false}, {"id": "b", "text": "remain constant.", "correct": true}, {"id": "c", "text": "increase.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'A process where temperature remains the same is known as', '[{"id": "a", "text": "isobaric.", "correct": false}, {"id": "b", "text": "isochoric.", "correct": false}, {"id": "c", "text": "isothermic.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'What is descriptive of Boyle''s Law? (P =Pressure, V= Volume, T =Temperature)', '[{"id": "a", "text": "P is proportional to 1/T.", "correct": false}, {"id": "b", "text": "P is proportional to 1/V.", "correct": true}, {"id": "c", "text": "P is proportional to T.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'A compressor increases', '[{"id": "a", "text": "kinetic energy.", "correct": false}, {"id": "b", "text": "potential energy.", "correct": true}, {"id": "c", "text": "moving energy.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'P₁V₁/T₁ = P₂V₂/T₂ is (P =Pressure, V = Volume, T =Temperature)', '[{"id": "a", "text": "Ideal gas law.", "correct": true}, {"id": "b", "text": "Charles'' law.", "correct": false}, {"id": "c", "text": "Boyle''s law.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'V₁/T₁ = V₂/T₂ at a constant pressure is (P = Pressure, V = Volume, T = Temperature)', '[{"id": "a", "text": "Ideal gas law.", "correct": false}, {"id": "b", "text": "Boyle''s law.", "correct": false}, {"id": "c", "text": "Charles'' law.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'P₁V₁ = P₂V₂ at a constant temperature is (P = Pressure, V= Volume, T =Temperature)', '[{"id": "a", "text": "Boyle''s law.", "correct": true}, {"id": "b", "text": "ideal gas law.", "correct": false}, {"id": "c", "text": "Charles'' law.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'The atmosphere''s temperature changes at a rate of -1.98 °C per 1000 ft up to 36,000 ft where it remains constant at', '[{"id": "a", "text": "-56 °F.", "correct": false}, {"id": "b", "text": "-52 °C.", "correct": false}, {"id": "c", "text": "-56 °C.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'A process where heat is given off to its surroundings is called', '[{"id": "a", "text": "isothermal.", "correct": true}, {"id": "b", "text": "adiabatic.", "correct": false}, {"id": "c", "text": "isobaric.", "correct": false}]'::jsonb, '{B1,B2}'),
