    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'The quantity of heat developed by burning 1 kg of fuel is known as', '[{"id": "a", "text": "radiant heat.", "correct": false}, {"id": "b", "text": "latent heat.", "correct": false}, {"id": "c", "text": "heat of combustion.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'The transfer of heat through radiation is achieved by', '[{"id": "a", "text": "the application of radioactive isotopes.", "correct": false}, {"id": "b", "text": "warming up the intervening medium.", "correct": false}, {"id": "c", "text": "not warming up the intervening medium.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'The dew point is', '[{"id": "a", "text": "the point at which air can be heated.", "correct": false}, {"id": "b", "text": "the point when air is cooled at which the moisture just starts to condense.", "correct": true}, {"id": "c", "text": "the point when air is cooled at which the moisture does not condense.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'What are common refrigerant agents?', '[{"id": "a", "text": "formaldehyde, ammonia, carbon dioxide.", "correct": false}, {"id": "b", "text": "water, freon, ammonia.", "correct": true}, {"id": "c", "text": "Dry ice, methyl bromide, water.", "correct": false}]'::jsonb, '{B1,B2}'),
