    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'During a pressurising process, all heat is given away. It is', '[{"id": "a", "text": "adiabatic.", "correct": false}, {"id": "b", "text": "isochoric.", "correct": false}, {"id": "c", "text": "isothermal.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'A material capable of going direct from solid to gas is a', '[{"id": "a", "text": "substrate.", "correct": false}, {"id": "b", "text": "substance.", "correct": false}, {"id": "c", "text": "sublimate.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'The composition of the atmosphere is approximately', '[{"id": "a", "text": "1/5 oxygen and 4/5 nitrogen.", "correct": true}, {"id": "b", "text": "4/5 oxygen and 1/5 nitrogen.", "correct": false}, {"id": "c", "text": "2/5 oxygen and 3/5 nitrogen.", "correct": false}]'::jsonb, '{B1,B2}'),
