    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'If a gas is heated and its temperature is raised by 1K. What happens to its volume?', '[{"id": "a", "text": "Decreases by 1/273.", "correct": false}, {"id": "b", "text": "Increases by 1/273.", "correct": true}, {"id": "c", "text": "Remains the same.", "correct": false}]'::jsonb, '{B1,B2}'),
