    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'The heat given off by burning a 1kg block of wood is', '[{"id": "a", "text": "transmissive heat.", "correct": false}, {"id": "b", "text": "radiant heat.", "correct": true}, {"id": "c", "text": "latent heat.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'H₂O in what form holds most energy?', '[{"id": "a", "text": "Steam.", "correct": true}, {"id": "b", "text": "Ice.", "correct": false}, {"id": "c", "text": "Water.", "correct": false}]'::jsonb, '{B1,B2}'),
