    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'A varying refractive index optical fibre is a', '[{"id": "a", "text": "single index.", "correct": false}, {"id": "b", "text": "graded index.", "correct": true}, {"id": "c", "text": "step index.", "correct": false}]'::jsonb, '{B1,B2}'),
