    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'A fibre optic cable has different refractive indexes across its core diameter, it is a', '[{"id": "a", "text": "single mode fibre.", "correct": false}, {"id": "b", "text": "graded index fibre.", "correct": true}, {"id": "c", "text": "step index fibre.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'Incident light travelling from air to water, the light is', '[{"id": "a", "text": "bent towards the normal.", "correct": true}, {"id": "b", "text": "not bent.", "correct": false}, {"id": "c", "text": "bent away from the normal.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'If a light is beamed at a flat mirror, what is the angle it reflects at?', '[{"id": "a", "text": "Reflective index.", "correct": false}, {"id": "b", "text": "Angle of incidence.", "correct": true}, {"id": "c", "text": "Reactive angle.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'In a graded index multimode fibre, the refractive index', '[{"id": "a", "text": "is high.", "correct": false}, {"id": "b", "text": "varies high and low.", "correct": true}, {"id": "c", "text": "is low", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'The fibre optic receiver is a', '[{"id": "a", "text": "photodiode.", "correct": true}, {"id": "b", "text": "laser diode.", "correct": false}, {"id": "c", "text": "light emitting diode.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'The usable bandwidth of a fibre is determined by', '[{"id": "a", "text": "the wavelength of the light.", "correct": false}, {"id": "b", "text": "the angle of total internal reflection.", "correct": false}, {"id": "c", "text": "the intermodal dispersion.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'If, with a concave mirror, the object is placed beyond the centre of curvature, the image produced will be', '[{"id": "a", "text": "virtual, erect and larger.", "correct": false}, {"id": "b", "text": "real, inverted and smaller.", "correct": true}, {"id": "c", "text": "real, erect and larger.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'The power of a lens is calculated from the', '[{"id": "a", "text": "reciprocal of the focal length.", "correct": true}, {"id": "b", "text": "product of the focal length and its distance from the pole.", "correct": false}, {"id": "c", "text": "focal length squared.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'Single mode optical fibre cable will', '[{"id": "a", "text": "have several light rays to pass.", "correct": false}, {"id": "b", "text": "have diameter matched to wavelength of light passed.", "correct": true}, {"id": "c", "text": "cause distortion to the light wave at the output end which is dependent upon the length of the cable.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'When an emergent light wave enters a divergent lens', '[{"id": "a", "text": "it will focus beyond the lens.", "correct": false}, {"id": "b", "text": "it will focus behind the lens.", "correct": true}, {"id": "c", "text": "it is s spherical.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'In a concave mirror, light rays parallel to mirror axis will be reflected', '[{"id": "a", "text": "through the focal point.", "correct": true}, {"id": "b", "text": "back to the centre of curvature.", "correct": false}, {"id": "c", "text": "parallel to mirror axis.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'In a concave mirror, a light ray passing through the focal point will be reflected', '[{"id": "a", "text": "through the focal point.", "correct": false}, {"id": "b", "text": "on the centre line of the mirror.", "correct": false}, {"id": "c", "text": "parallel to the axis.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'A passive sensor', '[{"id": "a", "text": "does not require power.", "correct": true}, {"id": "b", "text": "requires power for the sensor.", "correct": false}, {"id": "c", "text": "requires power for the transmitter.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'Refractive index is', '[{"id": "a", "text": "lower for 4ºC water than 0ºC ice.", "correct": false}, {"id": "b", "text": "higher for diamond than acrylic.", "correct": true}, {"id": "c", "text": "highest for water.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'For optical fibres, the refractive index of the cladding compared to that of the core', '[{"id": "a", "text": "can be either bigger or smaller depending on specification.", "correct": false}, {"id": "b", "text": "is always smaller.", "correct": true}, {"id": "c", "text": "is always larger.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'The ability for a fibreoptic cable to carry waves is dependent on', '[{"id": "a", "text": "material, absorption and speed of light.", "correct": false}, {"id": "b", "text": "internal reflection.", "correct": true}, {"id": "c", "text": "material, diameter and absorption.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'In spherical aberrations', '[{"id": "a", "text": "incident rays further from the axis intersect slightly closer to the lens to produce a distorted picture.", "correct": true}, {"id": "b", "text": "incident rays further from the axis intersect slightly further away from the lens to produce a distorted", "correct": false}, {"id": "c", "text": "picture.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'In a fibre optic flying control system', '[{"id": "a", "text": "the sensor and transmitter require electrical power.", "correct": true}, {"id": "b", "text": "the sensor inputs to the transmitter which needs electrical power.", "correct": false}, {"id": "c", "text": "the sensor needs electrical power.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'In fibreoptics, the type of cable is chosen by', '[{"id": "a", "text": "the strength of signal needed.", "correct": false}, {"id": "b", "text": "matching the diameter of the cable with the wavelength.", "correct": false}, {"id": "c", "text": "distance required to travel.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'When refraction takes place', '[{"id": "a", "text": "the frequency remains constant.", "correct": true}, {"id": "b", "text": "the speed of the wave remains constant.", "correct": false}, {"id": "c", "text": "the wavelength remains constant.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'When light meets a Glass / Air boundary at an angle of incidence less than the critical angle', '[{"id": "a", "text": "both reflection and refraction takes place.", "correct": true}, {"id": "b", "text": "no light is reflected.", "correct": false}, {"id": "c", "text": "total Internal Reflection takes place.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'An object placed more than twice the focal length beyond a converging lens will form an image that is', '[{"id": "a", "text": "inverted, larger and virtual.", "correct": false}, {"id": "b", "text": "inverted, smaller and real.", "correct": true}, {"id": "c", "text": "erect, smaller and real.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'A parabolic mirror may be used to prevent', '[{"id": "a", "text": "lateral inversion.", "correct": false}, {"id": "b", "text": "spherical aberration.", "correct": true}, {"id": "c", "text": "formation of a penumbra.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'The refractive index for air is approximately', '[{"id": "a", "text": "0.", "correct": false}, {"id": "b", "text": "1.", "correct": true}, {"id": "c", "text": "10.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'In optical fibres the total internal reflection of light only occurs at angles', '[{"id": "a", "text": "less than the critical angle.", "correct": false}, {"id": "b", "text": "equal to the critical angle.", "correct": false}, {"id": "c", "text": "greater than the critical angle.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'In a concave mirror, if an object is placed between the focal point and the pole, the image will be', '[{"id": "a", "text": "real, erect and diminished.", "correct": false}, {"id": "b", "text": "virtual and on the opposite side.", "correct": true}, {"id": "c", "text": "real, inverted and larger.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'The purpose of a patch cord used with an OTDR is', '[{"id": "a", "text": "to compensate for any contraction of the Fiber optic cable during test.", "correct": false}, {"id": "b", "text": "to overcome the dead zone problem caused by reflection at OTDR launch connector.", "correct": true}, {"id": "c", "text": "to attenuate OTDR output power which could cause damage to the cable under test.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'The power of a lens is measured in', '[{"id": "a", "text": "Lumens per Watt.", "correct": false}, {"id": "b", "text": "Watts.", "correct": false}, {"id": "c", "text": "Diopters.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'For a concave lens, the image is', '[{"id": "a", "text": "real.", "correct": false}, {"id": "b", "text": "virtual.", "correct": true}, {"id": "c", "text": "a chromatic orb.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'Lasers use which source of light?', '[{"id": "a", "text": "Scattered.", "correct": false}, {"id": "b", "text": "Refraction.", "correct": false}, {"id": "c", "text": "Coherent.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'Illumination of one lumen per metre squared is one', '[{"id": "a", "text": "luxor.", "correct": false}, {"id": "b", "text": "lux.", "correct": true}, {"id": "c", "text": "candle.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'The amount of light emitted by a lamp can be measured in', '[{"id": "a", "text": "candle''s.", "correct": false}, {"id": "b", "text": "luxors.", "correct": false}, {"id": "c", "text": "lumens.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'The light gathering power of a lens is indicated by its', '[{"id": "a", "text": "material.", "correct": false}, {"id": "b", "text": "thickness of the lens.", "correct": false}, {"id": "c", "text": "focal ratio.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'In order for a converging lens to form a real image, the object distance must be more than', '[{"id": "a", "text": "focal length.", "correct": true}, {"id": "b", "text": "5 times the thickness of the lens.", "correct": false}, {"id": "c", "text": "1 inch.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'A ______ lens is thicker in the middle than at the edges.', '[{"id": "a", "text": "converging", "correct": true}, {"id": "b", "text": "concave", "correct": false}, {"id": "c", "text": "upsharp", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'When is the only time a concave mirror forms a virtual image?', '[{"id": "a", "text": "When the object is at the focal point.", "correct": false}, {"id": "b", "text": "When the object is inside the focal point.", "correct": true}, {"id": "c", "text": "When the object is placed at the center of curvature.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'A convex mirror forms a virtual image when', '[{"id": "a", "text": "the object is at the centre of curvature.", "correct": false}, {"id": "b", "text": "the object is inside the focus.", "correct": false}, {"id": "c", "text": "always.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'A Concave mirror is used in', '[{"id": "a", "text": "a rear view mirror.", "correct": false}, {"id": "b", "text": "a periscope.", "correct": false}, {"id": "c", "text": "headlights.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'When the movement of an object rotating around a radius at a constant speed is projected onto a plane, the projected image follows what path?', '[{"id": "a", "text": "Sinusoidal.", "correct": true}, {"id": "b", "text": "Lateral.", "correct": false}, {"id": "c", "text": "Longitudinal.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'The speed of sound in air at 0 °C is approximately', '[{"id": "a", "text": "331 m/s.", "correct": true}, {"id": "b", "text": "3 × 10⁸ m/s.", "correct": false}, {"id": "c", "text": "181 m/s.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'If a wave traveling to a point meets a wave traveling from that point, of equal frequency', '[{"id": "a", "text": "the two waves cancel each other out.", "correct": false}, {"id": "b", "text": "they will have no effect on each other.", "correct": false}, {"id": "c", "text": "a standing wave is formed.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'Quality of sound depends upon', '[{"id": "a", "text": "pure sound waves being produced by the source.", "correct": false}, {"id": "b", "text": "frequency and harmonics of the waves being produced.", "correct": true}, {"id": "c", "text": "quality of the receiver.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'Particles vibrating in air', '[{"id": "a", "text": "tend to give off heat.", "correct": false}, {"id": "b", "text": "tend to give off light.", "correct": false}, {"id": "c", "text": "produce waves.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'The fundamental frequency is the', '[{"id": "a", "text": "1st harmonic.", "correct": true}, {"id": "b", "text": "2nd harmonic.", "correct": false}, {"id": "c", "text": "3rd harmonic.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'The first overtone of a sound wave is the', '[{"id": "a", "text": "1st harmonic.", "correct": false}, {"id": "b", "text": "2nd harmonic.", "correct": true}, {"id": "c", "text": "fundamental frequency.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'Two pure tones of similar frequency are heard by a person. What will they hear?', '[{"id": "a", "text": "One pure tone.", "correct": false}, {"id": "b", "text": "A beat of the two tones.", "correct": true}, {"id": "c", "text": "Two tones.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'Two sound waves of the same frequency and amplitude are moving half a wavelength out of phase with each other. What will be heard?', '[{"id": "a", "text": "Nothing.", "correct": true}, {"id": "b", "text": "Twice the volume of one of the sound waves.", "correct": false}, {"id": "c", "text": "Half the volume of one of the sound waves.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'A fire engine is approaching you with its siren on. As it passes you its pitch', '[{"id": "a", "text": "stay the same.", "correct": false}, {"id": "b", "text": "increases.", "correct": false}, {"id": "c", "text": "decreases.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'Quality of sound is dependent on', '[{"id": "a", "text": "number and pitch of harmonics.", "correct": true}, {"id": "b", "text": "medium it is travelling through.", "correct": false}, {"id": "c", "text": "frequency of the supply.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'What frequency is a tone which is 4 times the fundamental frequency?', '[{"id": "a", "text": "2nd overtone.", "correct": false}, {"id": "b", "text": "3rd overtone.", "correct": true}, {"id": "c", "text": "3rd harmonic.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'Intensity of sound waves', '[{"id": "a", "text": "is not affected by distance.", "correct": false}, {"id": "b", "text": "varies inversely as the square of distance from source.", "correct": true}, {"id": "c", "text": "vary directly as per distance from source.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'In a standing wave the point where continuous vibration of maximum amplitude occurs is called the', '[{"id": "a", "text": "harmonic.", "correct": false}, {"id": "b", "text": "anti-node.", "correct": true}, {"id": "c", "text": "node.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'The name given to sounds below that which the human ear can detect, i.e. below 20Hz is', '[{"id": "a", "text": "ultra sound.", "correct": false}, {"id": "b", "text": "infra sound.", "correct": true}, {"id": "c", "text": "sonic pitch.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'The speed of sound in dry air is 331 m/s. In a solid the speed would', '[{"id": "a", "text": "increase.", "correct": true}, {"id": "b", "text": "decrease.", "correct": false}, {"id": "c", "text": "stay the same.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'If a tuning fork is struck and held close to the ear and slowly rotated about the vertical axis, in one rotation how many times is there no sound?', '[{"id": "a", "text": "2.", "correct": false}, {"id": "b", "text": "4.", "correct": true}, {"id": "c", "text": "Sound is audible for the whole revolution.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'What is the phenomenon that occurs when a siren that approaches you, at the point of passing, the pitch decreases?', '[{"id": "a", "text": "Resonance.", "correct": false}, {"id": "b", "text": "Doppler effect.", "correct": true}, {"id": "c", "text": "Echo.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'For hearing protection, noise cancelling headphones', '[{"id": "a", "text": "cannot reduce the noise from outside completely.", "correct": false}, {"id": "b", "text": "operate by destructive interference of sound waves.", "correct": true}, {"id": "c", "text": "operate by constructive interference of sound waves.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'Tuning forks are used to vibrate musical instruments because', '[{"id": "a", "text": "they produce both of the other effects described.", "correct": false}, {"id": "b", "text": "they produce a beat when played together with the instrument.", "correct": false}, {"id": "c", "text": "they produce a pure note.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'When an open pipe is played and a note is heard', '[{"id": "a", "text": "the lowest frequency of the note is called second harmonic.", "correct": false}, {"id": "b", "text": "resonance occurs with standing waves set up inside the pipe.", "correct": true}, {"id": "c", "text": "there is a 180º phase change at the open end.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'Two sound waves are the same but slightly out of phase. This means that', '[{"id": "a", "text": "the beat frequency is the same.", "correct": false}, {"id": "b", "text": "there will be no beat frequency.", "correct": true}, {"id": "c", "text": "the beat frequency will be slightly different.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'In a vibrating string, the point at which there is no displacement is called a', '[{"id": "a", "text": "antinode.", "correct": false}, {"id": "b", "text": "node.", "correct": true}, {"id": "c", "text": "fundamental mode.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'The amplitude of a Transverse Wave is the distance from', '[{"id": "a", "text": "the top of a peak to the bottom of a trough.", "correct": false}, {"id": "b", "text": "half the distance from peak to trough.", "correct": true}, {"id": "c", "text": "one peak to the next.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'Increasing the Amplitude of a sound wave increases its', '[{"id": "a", "text": "pitch.", "correct": false}, {"id": "b", "text": "moment.", "correct": false}, {"id": "c", "text": "loudness.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'A wave in which the vibrations are perpendicular, or at right angles to the direction of wave travel is a', '[{"id": "a", "text": "Dispersion Wave.", "correct": false}, {"id": "b", "text": "Longitudinal Wave.", "correct": false}, {"id": "c", "text": "Transverse Wave.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'When a string vibrates, the point at which maximum displacement occurs is called the', '[{"id": "a", "text": "node.", "correct": false}, {"id": "b", "text": "antinode.", "correct": true}, {"id": "c", "text": "primary node.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'Increasing the frequency of a sound wave increases its', '[{"id": "a", "text": "pitch.", "correct": true}, {"id": "b", "text": "loudness.", "correct": false}, {"id": "c", "text": "moment.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'A wave in which the vibrations are parallel to, or along, the direction of travel is a', '[{"id": "a", "text": "Transverse Wave.", "correct": false}, {"id": "b", "text": "Upright Wave.", "correct": false}, {"id": "c", "text": "Longitudinal Wave.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'If a string is vibrating at the 3rd harmonic, it will be oscillating at', '[{"id": "a", "text": "Fundamental Frequency.", "correct": false}, {"id": "b", "text": "4 times its fundamental frequency.", "correct": false}, {"id": "c", "text": "3 times its fundamental frequency.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'The varying pitch of the sound of a train passing by is caused by a phenomenon known as', '[{"id": "a", "text": "Doppler effect.", "correct": true}, {"id": "b", "text": "double frequency.", "correct": false}, {"id": "c", "text": "resonance.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'Wavelength is', '[{"id": "a", "text": "distance from trough to crest.", "correct": false}, {"id": "b", "text": "distance between crests.", "correct": true}, {"id": "c", "text": "distance between top and bottom.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M02.6'), 'The speed of sound at standard atmospheric temperature and pressure is', '[{"id": "a", "text": "34 Km/s.", "correct": false}, {"id": "b", "text": "340 m/s.", "correct": true}, {"id": "c", "text": "340 Km/s.", "correct": false}]'::jsonb, '{B1,B2}'),
