-- Replaces M02's question bank with content grounded in the client's
-- supplied PDF (the previous content cited only a textbook title, not an actual
-- uploaded source -- see the M07 content audit and the M15/M16 fix this follows).
-- Old questions are removed except any already referenced by a completed exam's
-- exam_answers (no ON DELETE CASCADE there -- deleting them would corrupt real
-- historical results), which are left in place alongside the new content.

ON CONFLICT (code) DO NOTHING;

DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM questions q JOIN easa_subjects s ON s.id = q.subject_id WHERE s.code = 'M02.6') THEN
        RAISE NOTICE 'M02 already migrated to the new question bank, skipping.';
        RETURN;
    END IF;

    DELETE FROM questions q
    USING easa_subjects s
    WHERE q.subject_id = s.id AND s.module_id = 2
      AND q.id NOT IN (SELECT DISTINCT question_id FROM exam_answers);

END $$;
